package org.brightstats.desktop;

import java.util.*;
import javafx.geometry.Insets;
import javafx.scene.control.*;
import javafx.scene.layout.*;
import javafx.stage.Window;
import org.brightstats.stats.*;

final class NcaDialog {
    record Settings(String outcome,List<String> conditions,Nca.Options analysis,NcaPermutation.Options permutation){
        Settings{conditions=List.copyOf(conditions);Objects.requireNonNull(analysis);Objects.requireNonNull(permutation);if(outcome==null||outcome.isBlank()||conditions.isEmpty()||conditions.contains(outcome)||new HashSet<>(conditions).size()!=conditions.size()||!analysis.conditionScopes().isEmpty()&&analysis.conditionScopes().size()!=conditions.size())throw new IllegalArgumentException("Choose an outcome and distinct condition variables.");}
        void validate(List<String> columns){if(!columns.contains(outcome)||!columns.containsAll(conditions))throw new IllegalArgumentException("NCA settings refer to unavailable data columns.");}
    }
    private final Dialog<Settings> dialog=new Dialog<>();private final ComboBox<String> outcome=new ComboBox<>();private final ListView<String> conditions=new ListView<>();private final TextField steps=new TextField(),samples=new TextField(),seed=new TextField(),alpha=new TextField();private final CheckBox declared=new CheckBox("Use declared ranges instead of observed minimum/maximum"),retained=new CheckBox("Keep individual permutation effects in saved results");private final ComboBox<RegressionBootstrap.Convention> convention=new ComboBox<>();private final Map<String,TextField[]> ranges=new LinkedHashMap<>();private Settings settings;
    private NcaDialog(Window owner,List<String> names,double[][] data,Settings previous,boolean permute){
        if(names.size()<2)throw new IllegalArgumentException("NCA needs an outcome and at least one condition.");dialog.initOwner(owner);dialog.setTitle(permute?"NCA permutation test":"Necessary-condition analysis");var analysis=previous==null?Nca.Options.defaults():previous.analysis();var permutation=previous==null?NcaPermutation.Options.defaults():previous.permutation();
        outcome.getItems().setAll(names);outcome.setValue(previous==null?names.get(names.size()-1):previous.outcome());conditions.getItems().setAll(names);conditions.getSelectionModel().setSelectionMode(SelectionMode.MULTIPLE);conditions.setPrefHeight(180);for(String name:previous==null?names:previous.conditions())if(!name.equals(outcome.getValue()))conditions.getSelectionModel().select(name);outcome.valueProperty().addListener((o,a,b)->conditions.getSelectionModel().clearSelection(names.indexOf(b)));steps.setText(Integer.toString(analysis.steps()));
        Label explanation=UiAppearance.label("Identify conditions needed for high outcomes using CE-FDH and CR-FDH ceiling lines. This does not establish causation or measure an average regression effect. Select conditions with Ctrl/Shift; the outcome cannot also be a condition.");explanation.setWrapText(true);VBox basic=new VBox(8,explanation,UiAppearance.label("Outcome"),outcome,UiAppearance.label("Conditions"),conditions,UiAppearance.label("Bottleneck steps"),steps);basic.setPadding(new Insets(12));
        GridPane grid=new GridPane();grid.setHgap(8);grid.setVgap(6);grid.addRow(0,UiAppearance.label("Variable"),UiAppearance.label("Minimum"),UiAppearance.label("Maximum"));for(int j=0;j<names.size();j++){String name=names.get(j);int index=j;double minimum=Arrays.stream(data).mapToDouble(row->row[index]).min().orElseThrow(),maximum=Arrays.stream(data).mapToDouble(row->row[index]).max().orElseThrow();Nca.Bounds prior=name.equals(outcome.getValue())?analysis.outcomeScope():previous!=null&&previous.conditions().contains(name)&&!analysis.conditionScopes().isEmpty()?analysis.conditionScopes().get(previous.conditions().indexOf(name)):null;var low=new TextField(Double.toString(prior==null?minimum:prior.minimum()));var high=new TextField(Double.toString(prior==null?maximum:prior.maximum()));ranges.put(name,new TextField[]{low,high});grid.addRow(j+1,new Label(name),low,high);}
        declared.setSelected(!analysis.conditionScopes().isEmpty()||analysis.outcomeScope()!=null);grid.disableProperty().bind(declared.selectedProperty().not());VBox scope=new VBox(8,declared,UiAppearance.label("Declared ranges must contain every selected observation."),grid);scope.setPadding(new Insets(12));ScrollPane scopeScroll=new ScrollPane(scope);scopeScroll.setFitToWidth(true);
        samples.setText(Integer.toString(permutation.samples()));seed.setText(Long.toString(permutation.seed()));alpha.setText(Double.toString(permutation.significance()));convention.getItems().setAll(RegressionBootstrap.Convention.values());convention.setValue(permutation.convention());retained.setSelected(permutation.retainDraws());VBox inference=new VBox(8,UiAppearance.label("Permute outcome labels while preserving condition rows. At least 1000 permutations are recommended for final inference."),UiAppearance.label("Permutations"),samples,UiAppearance.label("Random seed"),seed,UiAppearance.label("Significance level"),alpha,UiAppearance.label("Sampling/probability convention"),convention,retained);inference.setPadding(new Insets(12));Tab inferTab=new Tab("Permutation",inference);inferTab.setDisable(!permute);TabPane tabs=new TabPane(new Tab("Variables",basic),new Tab("Scopes",scopeScroll),inferTab);for(var tab:tabs.getTabs())tab.setClosable(false);Label error=new Label();error.setWrapText(true);VBox content=new VBox(8,tabs,error);content.setPadding(new Insets(12));content.setPrefSize(650,600);dialog.getDialogPane().setContent(content);dialog.setResizable(true);dialog.getDialogPane().getButtonTypes().setAll(ButtonType.OK,ButtonType.CANCEL);
        dialog.getDialogPane().lookupButton(ButtonType.OK).addEventFilter(javafx.event.ActionEvent.ACTION,event->{settings=null;try{List<String> selected=List.copyOf(conditions.getSelectionModel().getSelectedItems());List<Nca.Bounds> bounds=declared.isSelected()?selected.stream().map(this::bounds).toList():List.of();var chosen=new Nca.Options(Integer.parseInt(steps.getText().trim()),bounds,declared.isSelected()?bounds(outcome.getValue()):null,analysis.exclusionLimit(),analysis.exclusionStep(),analysis.accuracyTolerance());var nullOptions=permute?new NcaPermutation.Options(Integer.parseInt(samples.getText().trim()),Long.parseLong(seed.getText().trim()),Double.parseDouble(alpha.getText().trim()),convention.getValue(),retained.isSelected()):permutation;settings=new Settings(outcome.getValue(),selected,chosen,nullOptions);settings.validate(names);}catch(Exception problem){event.consume();error.setText(problem.getMessage());}});dialog.setResultConverter(button->button==ButtonType.OK?settings:null);
    }
    private Nca.Bounds bounds(String name){var values=ranges.get(name);return new Nca.Bounds(Double.parseDouble(values[0].getText().trim()),Double.parseDouble(values[1].getText().trim()));}
    static Optional<Settings> show(Window owner,List<String> names,double[][] data,Settings previous,boolean permute){return new NcaDialog(owner,names,data,previous,permute).dialog.showAndWait();}
    static Settings smokeTest(Window owner,List<String> names,double[][] data){var test=new NcaDialog(owner,names,data,null,true);test.dialog.show();test.steps.setText("0");((Button)test.dialog.getDialogPane().lookupButton(ButtonType.OK)).fire();if(!test.dialog.isShowing()||test.settings!=null)throw new AssertionError("Invalid NCA steps accepted");test.steps.setText("10");test.samples.setText("29");((Button)test.dialog.getDialogPane().lookupButton(ButtonType.OK)).fire();if(!test.dialog.isShowing()||test.settings!=null)throw new AssertionError("Invalid NCA permutation count accepted");test.samples.setText("40");test.conditions.getSelectionModel().clearSelection();test.conditions.getSelectionModel().selectIndices(0,1);test.retained.setSelected(true);((Button)test.dialog.getDialogPane().lookupButton(ButtonType.OK)).fire();if(test.dialog.getResult()==null)throw new AssertionError("NCA settings lost");return test.dialog.getResult();}
}
